import {inspectConfirmedArchive} from './archiveTransfer';
import {clone,SyncProtocolError,valueHash,type SyncOperation} from './protocol';
import {bootstrapNativeProject,applyNativeOperation,type AtomicSyncRepository,type ServerIdentity,type ServerState} from './server';
import {applyEditorOperation,readEditorImage,scopedDocuments,type EditorServerState} from './editor';
import type {ProjectData} from '../domain/types';
import {ID_PATTERN} from '../domain/model';
import {preparePublicExecution} from '../domain/exportPreparation';
import {attachmentMetadata,assetPath,validateAsset,worldSnapshotContents} from '../storage/archive';
import {jsonBytes,sha256} from '../storage/json';
export interface SyncEdgeEnvironment {url:string;publishableKey:string;serviceRoleKey:string;allowedOrigins:string[]}
type RPC=(name:string,args:Record<string,unknown>)=>Promise<unknown>;
const fail=(code:'FORBIDDEN'|'AUTH_REQUIRED'|'PROTOCOL_INVALID'|'TRANSPORT_UNAVAILABLE'|'REVISION_CHANGED'):never=>{throw new SyncProtocolError(code);};
function object(value:unknown){if(!value||typeof value!=='object'||Array.isArray(value))fail('PROTOCOL_INVALID');return value as Record<string,unknown>;}
function uuid(value:unknown){if(typeof value!=='string'||!ID_PATTERN.test(value))fail('PROTOCOL_INVALID');return value as string;}
function jwtClaims(token:string){try{return object(JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))));}catch{return fail('AUTH_REQUIRED');}}
/** The verified Auth identity is still checked against live sessions/membership inside every RPC. */
export function createSyncEdgeHandler(env:SyncEdgeEnvironment,fetcher:typeof fetch=fetch){
 const captured=clone(env),url=new URL(captured.url);if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1'].includes(url.hostname)))throw Error('DEDICATED_ENDPOINT_REQUIRED');
 const serviceHeaders={apikey:captured.serviceRoleKey,Authorization:`Bearer ${captured.serviceRoleKey}`,'Content-Type':'application/json'};
 const rpc:RPC=async(name,args)=>{const response=await fetcher(`${url.origin}/rest/v1/rpc/${name}`,{method:'POST',headers:serviceHeaders,body:JSON.stringify(args)});if(!response.ok){const raw=await response.json().catch(()=>({})),message=String(raw.message??'');if(message.includes('AUTH_REQUIRED'))fail('AUTH_REQUIRED');if(response.status===403||message.includes('FORBIDDEN'))fail('FORBIDDEN');if(message.includes('REVISION_CHANGED'))fail('REVISION_CHANGED');fail('PROTOCOL_INVALID');}return response.status===204?null:response.json();};
 const repository:AtomicSyncRepository={
  read:async(i,project,base,operation)=>await rpc('scenario_sync_engine_context',{p_actor:i.accountId,p_session:i.sessionId,p_project:project,p_base:base,p_operation:operation}) as ServerState,
  bootstrap:async(i,input)=>await rpc('scenario_sync_bootstrap',{actor:i.accountId,session:i.sessionId,project:input.project.projectId,image:input.project,documents:input.documents,worlds:input.worlds}) as Awaited<ReturnType<AtomicSyncRepository['bootstrap']>>,
  commit:async(i,input)=>await rpc('scenario_sync_commit_prepared',{actor:i.accountId,session:i.sessionId,project:input.projectId,expected_revision:input.expectedRevision,operation:input.operation,operation_hash:input.operationHash,ack:input.ack,documents:input.documents,image:input.image,derived_ids:input.derivedIds??[]}) as Awaited<ReturnType<AtomicSyncRepository['commit']>>,
 };
 const identity=async(request:Request):Promise<ServerIdentity>=>{const bearer=request.headers.get('Authorization');if(!bearer?.startsWith('Bearer '))fail('AUTH_REQUIRED');const token=bearer!.slice(7),response=await fetcher(`${url.origin}/auth/v1/user`,{headers:{apikey:captured.publishableKey,Authorization:`Bearer ${token}`}});if(!response.ok)fail('AUTH_REQUIRED');const user=object(await response.json()),claims=jwtClaims(token);if(user.id!==claims.sub||typeof claims.exp!=='number'||claims.exp*1000<=Date.now())fail('AUTH_REQUIRED');return {accountId:uuid(user.id),sessionId:uuid(claims.session_id)};};
 const apiArgs=(i:ServerIdentity,projectId:string)=>({p_actor:i.accountId,p_session:i.sessionId,p_project:projectId});
 async function owner(i:ServerIdentity,id:string,expected?:unknown){const state=await repository.read(i,id,null,null);if(state.role!=='owner')fail('FORBIDDEN');if(expected!==undefined&&state.serverRevision!==expected)fail('REVISION_CHANGED');return state;}
 return async(request:Request):Promise<Response>=>{
  const origin=request.headers.get('Origin'),cors:Record<string,string>=origin&&captured.allowedOrigins.includes(origin)?{'Access-Control-Allow-Origin':origin,Vary:'Origin'}:{};
  const json=(data:unknown,status=200)=>new Response(JSON.stringify(data),{status,headers:{...cors,'Content-Type':'application/json','Cache-Control':'no-store'}});
  try{
   if(origin&&!captured.allowedOrigins.includes(origin))fail('FORBIDDEN');if(request.method==='OPTIONS')return new Response(null,{status:204,headers:{...cors,'Access-Control-Allow-Methods':'POST, OPTIONS','Access-Control-Allow-Headers':'authorization, apikey, content-type'}});if(request.method!=='POST')fail('PROTOCOL_INVALID');
   const actor=await identity(request),length=Number(request.headers.get('Content-Length'));if(length>128*1024*1024)fail('PROTOCOL_INVALID');const text=await request.text();if(new TextEncoder().encode(text).byteLength>128*1024*1024)fail('PROTOCOL_INVALID');const envelope=object(JSON.parse(text));if(envelope.specification!=='scenario-sync-native/1.0.0')fail('PROTOCOL_INVALID');const input=object(envelope.input),action=envelope.action;let result:unknown;
   if(action==='bootstrap')result=await bootstrapNativeProject(repository,actor,input as unknown as {project:ProjectData;worlds:Record<string,ProjectData>});
   else if(action==='apply'){const op=input as unknown as SyncOperation;const state=await repository.read(actor,uuid(op.scope?.projectId),null,null);result=state.role==='owner'?await applyNativeOperation(repository,actor,op):await applyEditorOperation(repository,actor,op);}
   else if(action==='pull'){const state=await owner(actor,uuid(input.projectId));result={project:state.nativeImage,worlds:state.worlds,serverRevision:state.serverRevision,documents:state.documents,contentHash:await valueHash(state.documents)};}
   else if(action==='team_read')result=await readEditorImage(repository,actor,uuid(input.projectId));
   else if(action==='projects')result=await rpc('scenario_owned_projects',{p_actor:actor.accountId,p_session:actor.sessionId});
   else if(action==='shared_snapshot')result=await rpc('scenario_shared_snapshot',{p_actor:actor.accountId,p_session:actor.sessionId,p_snapshot:uuid(input.snapshotId)});
   else if(action==='shares')result=await rpc('scenario_project_shares',apiArgs(actor,uuid(input.projectId)));
   else if(action==='members')result=await rpc('scenario_project_members',apiArgs(actor,uuid(input.projectId)));
   else if(action==='membership'){const project=uuid(input.projectId);await rpc('scenario_membership',{actor:actor.accountId,session:actor.sessionId,project,account:uuid(input.accountId),new_role:input.role,expires_at:input.expiresAt??null,revoked:input.revoked===true,snapshots:input.snapshotIds??[],expected_membership:input.membershipRevision});result={saved:true};}
   else if(action==='editor_grants'){const project=uuid(input.projectId),state=await owner(actor,project,input.serverRevision),scopes=clone(input.scopes) as EditorServerState['scopes'];scopedDocuments({...state,role:'editor',scopes});await rpc('scenario_editor_grants',{...apiArgs(actor,project),p_account:uuid(input.accountId),p_scopes:scopes,p_expected:state.serverRevision,p_membership:input.membershipRevision});result={saved:true};}
   else if(action==='publish'){const project=uuid(input.projectId),state=await owner(actor,project,input.serverRevision),sourceVersionId=uuid(input.sourceVersionId),pin=state.nativeImage.snapshots.find(s=>s.id===sourceVersionId);if(!pin)fail('PROTOCOL_INVALID');const prepared=await preparePublicExecution(state.nativeImage,{profile:'reader',projectionProfileId:uuid(input.profileId),targetVersionId:sourceVersionId,worldSnapshots:worldSnapshotContents(state.worlds),worldPins:Object.values(state.worlds).flatMap(w=>w.snapshots)}),hash=await sha256(jsonBytes(prepared.projection)),assets=[{id:'public-project',projection:prepared.projection},...(prepared.projection.versions??[])].flatMap(v=>v.projection.entities.filter(e=>e.kind==='attachment').map(e=>({publicId:v.id==='public-project'?e.id:v.id+':'+e.id,hash:e.data.contentHash})));if(input.projectionHash!==hash)fail('REVISION_CHANGED');result=await rpc('scenario_publish',{...apiArgs(actor,project),p_expected:state.serverRevision,p_snapshot:crypto.randomUUID(),p_public_project:'public-project',p_source:sourceVersionId,p_source_hash:pin!.contentHash,p_projection:prepared.projection,p_hash:hash,p_expires:input.expiresAt??null,p_assets:assets});}
   else if(action==='withdraw'){await rpc('scenario_withdraw',{...apiArgs(actor,uuid(input.projectId)),p_snapshot:uuid(input.snapshotId)});result={withdrawn:true};}
   else if(action==='upload_asset'){const project=uuid(input.projectId),state=await owner(actor,project),hash=String(input.contentHash),meta=[state.nativeImage,...Object.values(state.worlds)].flatMap(attachmentMetadata).find(m=>m.contentHash===hash);if(!meta||typeof input.base64!=='string')fail('PROTOCOL_INVALID');if((input.base64 as string).length>Math.ceil(32*1024*1024/3)*4)fail('PROTOCOL_INVALID');const bytes=Uint8Array.from(atob(input.base64 as string),ch=>ch.charCodeAt(0));if(bytes.byteLength!==meta!.byteSize||await sha256(bytes)!==hash)fail('PROTOCOL_INVALID');validateAsset(assetPath(hash,meta!.mediaType),meta!.mediaType,bytes);const path=`${project}/${hash}`,storageURL=`${url.origin}/storage/v1/object/scenario-private/${path}`,response=await fetcher(storageURL,{method:'POST',headers:{...serviceHeaders,'Content-Type':meta!.mediaType,'x-upsert':'false'},body:bytes});if(!response.ok){const prior=await fetcher(storageURL,{headers:serviceHeaders});if(!prior.ok||await sha256(new Uint8Array(await prior.arrayBuffer()))!==hash)fail('TRANSPORT_UNAVAILABLE');}await owner(actor,project);const item=state.nativeImage.entities.find(e=>e.kind==='attachment'&&e.data.contentHash===hash);await rpc('scenario_asset_complete',{...apiArgs(actor,project),p_hash:hash,p_size:bytes.byteLength,p_type:meta!.mediaType,p_path:path,p_visibility:item?.visibility??'private'});result={contentHash:hash,bytes:bytes.byteLength};}
   else if(action==='upload_archive'){const project=uuid(input.projectId),state=await owner(actor,project,input.serverRevision);if(typeof input.base64!=='string'||input.base64.length>Math.ceil(64*1024*1024/3)*4)fail('PROTOCOL_INVALID');const bytes=Uint8Array.from(atob(input.base64 as string),ch=>ch.charCodeAt(0));await inspectConfirmedArchive(bytes,project,state.documents);const hash=await sha256(bytes);if(hash!==input.contentHash)fail('PROTOCOL_INVALID');const path=`${project}/${state.serverRevision}/${hash}`,storageURL=`${url.origin}/storage/v1/object/scenario-backups/${path}`,response=await fetcher(storageURL,{method:'POST',headers:{...serviceHeaders,'Content-Type':'application/octet-stream','x-upsert':'false'},body:bytes});if(!response.ok){const old=await fetcher(storageURL,{headers:serviceHeaders});if(!old.ok||await sha256(new Uint8Array(await old.arrayBuffer()))!==hash)fail('TRANSPORT_UNAVAILABLE');}await owner(actor,project,state.serverRevision);await rpc('scenario_archive_complete',{...apiArgs(actor,project),p_revision:state.serverRevision,p_hash:hash,p_size:bytes.byteLength,p_path:path});result={contentHash:hash,bytes:bytes.byteLength,serverRevision:state.serverRevision};}
   else if(action==='download_archive'){const args={...apiArgs(actor,uuid(input.projectId)),p_revision:input.serverRevision??null},access=object(await rpc('scenario_archive_access',args)),response=await fetcher(`${url.origin}/storage/v1/object/scenario-backups/${access.path}`,{headers:serviceHeaders});if(!response.ok)fail('TRANSPORT_UNAVAILABLE');if(Number(response.headers.get('Content-Length'))>64*1024*1024)fail('PROTOCOL_INVALID');const bytes=new Uint8Array(await response.arrayBuffer());if(bytes.byteLength>64*1024*1024||bytes.byteLength!==access.byteSize||await sha256(bytes)!==access.contentHash)fail('PROTOCOL_INVALID');await rpc('scenario_archive_access',args);return new Response(bytes,{headers:{...cors,'Content-Type':'application/octet-stream','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});}
   else if(action==='download_asset'){const publicRequest=input.snapshotId!==undefined,name=publicRequest?'scenario_public_asset_access':'scenario_asset_access',args=publicRequest?{p_actor:actor.accountId,p_session:actor.sessionId,p_snapshot:uuid(input.snapshotId),p_public_id:String(input.publicAssetId)}:{...apiArgs(actor,uuid(input.projectId)),p_hash:String(input.contentHash),p_snapshot:null,p_public_id:null},access=object(await rpc(name,args));const response=await fetcher(`${url.origin}/storage/v1/object/scenario-private/${access.path}`,{headers:serviceHeaders});if(!response.ok)fail('TRANSPORT_UNAVAILABLE');const bytes=new Uint8Array(await response.arrayBuffer());if(bytes.byteLength!==access.byteSize||await sha256(bytes)!==access.contentHash)fail('PROTOCOL_INVALID');await rpc(name,args);return new Response(bytes,{headers:{...cors,'Content-Type':String(access.mediaType),'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});}
   else fail('PROTOCOL_INVALID');
   return json(result);
  }catch(cause){const code=cause instanceof SyncProtocolError?cause.code:'PROTOCOL_INVALID';return json({code},code==='AUTH_REQUIRED'?401:code==='FORBIDDEN'?403:code==='REVISION_CHANGED'?409:400);}
 };
}
